use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},fmt::Write};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-poseidon-fused-dot";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-27-poseidon-fused-dot";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);let d=Path::new(D);let full=r.join("performance-analysis.json").exists();let stage=if full{"performance"}else{"screen"};let a=read(r.join(format!("{stage}-analysis.json")));let protocol=read(r.join(stage).join("protocol.json"));for(p,h)in protocol["pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap(),"closing pin {p}");}let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");for(p,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());}assert_eq!(hash("/tmp/zopro-grouping-module/native/candidate-sdk"),"03e1260e89068c2bec37a2471c34e93628a9f081903e1b7eee9cab9c306aaf3d");let context=read(r.join("context-audit.json"));assert_eq!(hash(context["source"].as_str().unwrap()),context["source_sha256"].as_str().unwrap());
 assert_eq!(read(r.join("native/core/tests.json"))["passed_tests"].as_array().unwrap().len(),111);let inventory=read(r.join("proof-inventory.json"));let mut seen=BTreeSet::new();for(p,h)in inventory.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());if p.ends_with(".proof"){assert_eq!(fs::metadata(p).unwrap().len(),164);assert!(seen.insert(h.as_str().unwrap()));}}assert_eq!(seen.len(),a["independent_exports"].as_u64().unwrap()as usize);assert_eq!(inventory.as_object().unwrap().len(),seen.len()*2);
 let audit=json!({"status":if full{"full SDK study complete; review required before adoption"}else{"short SDK screen closed; no advancement"},"native_core_tests":111,"new_core_tests":2,"raw_tests":2,"cubic_tests":6,"field_sources_and_qualification_inherited_unchanged":true,"independent_all_width_buffer_comparisons":384,"all_width_adversarial_rejections":48,"all_width_tail_error_comparisons":48,"production_sources_checked_unchanged":170,"pins_checked":protocol["pins"].as_object().unwrap().len(),"SDK_requests":a["sdk_requests"],"independent_gnark_exports":a["independent_exports"],"proof_public_members":inventory.as_object().unwrap().len(),"next_prior_count":a["next_prior_count"],"full_stage_executed":full,"new_profiles":if full{3}else{0},"screen_repeated":false,"adopted":false,"candidate_retained":true,"goal_achieved":false,"next_action":if full{"Review all full-matrix gates, resource/compiler/profile evidence against the original all-eight10x target; never adopt from a single cell. Preserve measured small gains without imposing a floor."}else{"Keep the actual scalar fused-dot candidate and complete screen evidence. Do not rerun this unchanged screen or relax its gates. Inspect actual dot code generation and source-level intermediate additions before another distinct change; no new grouping/pool/table mechanism follows from this trial. All-eight10x remains unmet."}});save(r.join("closeout.json"),&audit);
 let mut md=format!("# Scalar fused Poseidon dot products\n\nThe {} is complete. Screen advances: **{}**; full qualification passes: **{}**. The candidate is retained and production is unchanged. No minimum positive-gain threshold is used.\n\nThe original scalar Poseidon executor now pairs adjacent dot-product terms with the field library's existing `Fr::sum_of_products`, sharing one Montgomery reduction between two products. An odd final term retains ordinary multiplication. This applies to dense matrices and each partial round's rest term for recognized widths 2–13, including the smallest circuit. S-boxes, constants, prefixes, sparse updates and every original wire/slot/A/B/C write remain unchanged.\n\nThis changes one original source file and adds one private helper with two tests. The other 169 originals remain byte-identical. No field primitive, runtime experiment flag, scheduler, point/constant table, copied plan, heap scratch, thread pool, image format or resource policy is added. It uses the existing scalar backend and does not reduce independent-task parallelism.\n\nThe preceding [parallel grouping result](../2026-10-27-poseidon-parallel/README.md) prompted a structural check: every wholly-width-three eligible task contributes to the first width-three frontier, so the earlier model's maximum bounds its count. All eight original circuits have at most 52 such tasks per epoch. The previous grouping guard requires more than 64 at 32 workers and therefore cannot enable for those eight circuits. [Context audit](artifacts/context-audit.json) checks the saved census and its hash. This new scalar substitution has no batch-occupancy requirement; no speedup is inferred from the census.\n\n## Complete SDK measurements\n\nThe exact historical accepted binary, a fresh unmodified build and the fused candidate use the same standard SDK consumer, compiler flags, allocator policy and inputs. Request timers include witness construction, fresh blinded proving, self-verification and serialization; key loading and three primes occur outside capture. Ratios pair process medians within rotated/reversed fresh-process blocks. CPU time includes scheduling; process lifetime RSS includes loading and primes and is neither minimum RAM nor mode-specific working memory.\n\n|Case|Accepted ms|Fresh ms|Fused ms|Fused/accepted|Fused/fresh|Saving vs fresh µs|Wins vs fresh|Fused RSS MiB|Fused CPU ms/request|\n|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|\n",if full{"full SDK study"}else{"short SDK screen"},read(r.join("screen-analysis.json"))["screen_advances_to_full"],a["full_gate_passed"]);
 for(name,c)in a["cases"].as_object().unwrap(){let modes=&c["modes"];let p=&c["pairs"];writeln!(md,"|{name}|{:.6}|{:.6}|{:.6}|{:.6}|{:.6}|{:.3}|{}|{:.2}|{:.3}|",modes["accepted"]["ms"].as_f64().unwrap(),modes["fresh"]["ms"].as_f64().unwrap(),modes["fused"]["ms"].as_f64().unwrap(),p["fused/accepted"]["geometric_ratio"].as_f64().unwrap(),p["fused/fresh"]["geometric_ratio"].as_f64().unwrap(),p["fused/fresh"]["saving_us"].as_f64().unwrap(),p["fused/fresh"]["wins"],modes["fused"]["maxrss_mib"].as_f64().unwrap(),modes["fused"]["cpu_ms_per_request"].as_f64().unwrap()).unwrap();}
 md.push_str("\nThe screen has three blocks and 17 timed requests per process at primary 16 and 32 workers. Its declared rule requires fresh/accepted calibration within factor 1.05 in every block and factor 1.03 for paired medians, a primary32 improvement against both controls in at least two of three blocks, and both cases within 2% nonregression against both controls. Any failure remains included. There are no successful repeats or discarded cells.\n\n");for(key,title)in [("calibration_failures","Calibration"),("primary_failures","Primary improvement"),("regressions","Nonregression")]{writeln!(md,"{title} failures: `{}`.\n",a[key]).unwrap();}
 if full{md.push_str("The full stage uses seven blocks for all nine circuits at 32 workers plus primary16, then three warm-gated profiles after all latency captures. The full rule requires control calibration in every case, primary32 improvement against both controls with at least four of seven wins, all-case nonregression within 2%, and an improvement or tie in the original-eight geometric aggregate against both controls.\n\n|Shape|Fused ms|M5 CPU ms|CPU/fused|M5 Metal ms|Metal/fused|\n|---|---:|---:|---:|---:|---:|\n");for c in a["cases"].as_object().unwrap().values().filter(|c|c["workers"]==32){let ms=c["modes"]["fused"]["ms"].as_f64().unwrap();if let(Some(cpu),Some(metal))=(c["reference"]["cpu_ms"].as_f64(),c["reference"]["metal_ms"].as_f64()){writeln!(md,"|{}|{ms:.6}|{cpu:.0}|{:.3}|{metal:.0}|{:.3}|",c["shape"].as_str().unwrap(),cpu/ms,metal/ms).unwrap();}else{writeln!(md,"|{}|{ms:.6}|—|—|—|—|",c["shape"].as_str().unwrap()).unwrap();}}}else{assert!(!r.join("performance").exists());md.push_str("The full stage and cycle profiles did not run. No arithmetic-only benchmark was used to select or reject this candidate. The [last complete all-shape SDK matrix](../2026-10-26-pairing-x-chain-sdk/README.md) retains the full supplied M5 CPU/Metal comparison and remains the performance reference outside this short screen.\n");}
 md.push_str("\n## Validation and scope\n\nAll 111 native core tests, two raw tests, six cubic tests, generator check, and portable/no-IFMA consumer checks pass. New helper tests compare empty/odd/even dot products through length 13 with separate multiplication/addition across boundary and random input families, and exercise actual width-three dense/partial constants. Existing independent symbolic fixtures compare 384 complete-buffer executions across widths 2–13, normal/reversed operands, omitted/materialized C, and adversarial inputs; 48 malformed recognitions and 48 tail-error comparisons are retained. Field source and prior qualification are unchanged; no new field-suite run is claimed.\n\nAll nine circuits pass a four-worker preflight for both fresh and fused binaries: 72 SDK requests and 18 independent Gnark exports. Every exported proof from subsequent measured stages is also checked for its 164-byte length, pinned public-input hash, fresh identity against the complete preceding ledger, and independent Gnark verification. The inventory does not count internal priming proofs as exported identities.\n\n");writeln!(md,"Total **{} SDK requests**, **{} distinct independently verified exports**, **{} proof/public members**; next proof-ledger count **{}**. Full stage executed: **{}**; new cycle profiles: **{}**. The full all-eight CPU10× objective remains active and unmet; no production adoption follows from this report.\n",a["sdk_requests"],a["independent_exports"],inventory.as_object().unwrap().len(),a["next_prior_count"],full,if full{3}else{0}).unwrap();md.push_str("No owned helper, build, hash or archive runs alongside SDK timing/profile captures. All pins and proof members are checked again at close. No new AWS/Aeglos, phone, TEE, giant-circuit, swap, minimum-RAM, memory-pressure, concurrent-prover or throughput qualification is claimed.\n\n");for mode in ["fresh","fused"]{let b=read(r.join(format!("native/{mode}/artifacts.json")));writeln!(md,"{mode} executable: `{}`; SHA-256 `{}`.\n",b["binary"].as_str().unwrap(),b["binary_sha256"].as_str().unwrap()).unwrap();}md.push_str("[Design](artifacts/design.md), [implementation audit](artifacts/implementation-audit.json), [screen analysis](artifacts/screen-analysis.json), [native tests](artifacts/native/core/tests.json), [proof inventory](artifacts/proof-inventory.json), [artifact hashes](artifact-index.json).\n");fs::create_dir_all(d).unwrap();fs::write(d.join("README.md"),md).unwrap();fs::copy("/tmp/zopro-grouping-module/production-source-manifest.json",r.join("accepted-source-manifest.json")).unwrap();let mut index=BTreeMap::new();archive(r,r,&d.join("artifacts"),&mut index);for(rel,h)in &index{assert_eq!(&hash(d.join("artifacts").join(rel)),h);}for(p,h)in inventory.as_object().unwrap(){let rel=Path::new(p).strip_prefix(r).unwrap();assert_eq!(hash(d.join("artifacts").join(rel)),h.as_str().unwrap());}save(d.join("artifact-index.json"),&json!(index));println!("{}archive hashes/{}proof members checked;nextprior{}",index.len(),inventory.as_object().unwrap().len(),a["next_prior_count"]);}
fn archive(root:&Path,here:&Path,dest:&Path,index:&mut BTreeMap<String,String>){let mut entries:Vec<_>=fs::read_dir(here).unwrap().map(|e|e.unwrap().path()).collect();entries.sort();for p in entries{let rel=p.strip_prefix(root).unwrap();let s=rel.display().to_string();if s.starts_with("target-"){continue;}if p.is_dir(){archive(root,&p,dest,index);continue;}if (s.starts_with("baseline/")||s.starts_with("candidate/"))&&!["baseline/crates/zopro-core/src/solver/sparse_poseidon.rs","candidate/crates/zopro-core/src/solver/sparse_poseidon.rs","candidate/crates/zopro-core/src/solver/sparse_poseidon/dot.rs"].contains(&s.as_str()){continue;}if !["json","jsonl","rs","md","txt","log","proof","public"].iter().any(|x|p.extension().is_some_and(|e|e==*x)){continue;}let q=dest.join(rel);fs::create_dir_all(q.parent().unwrap()).unwrap();fs::copy(&p,&q).unwrap();let h=hash(&q);assert_eq!(h,hash(&p));index.insert(s,h);}}
